mapper.select:
select billId, regDentistId, employeeName, orderDate, orderNum, billDate, billNum, patientId, `name`, mobile, originalPrice, privilegeAmount, actualAmount, receivedAmount, debtAmount from ( SELECT bill_id AS billId, btp.registered_dentist_id AS regDentistId, btp.employee_name AS employeeName, date_format(bb.order_date, '%Y-%m-%d') AS orderDate, bb.order_num AS orderNum, date_format(bb.bill_date, '%Y-%m-%d') AS billDate, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name`, bp.pinyin_name AS pinyinName, bp.mobile, bb.order_amount AS originalPrice, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, bb.debt_amount AS debtAmount FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.org_id, btp.treatment_id, btp.registered_dentist_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL ) btp ON bb.treatment_id = btp.treatment_id AND bb.org_id = btp.org_id
bb.debt_amount > 0
AND bb.org_id = #{form.orgId}
and DATE_FORMAT(bb.order_date, "%Y-%m-%d") >= DATE_FORMAT(#{form.startDate}, "%Y-%m-%d") and DATE_FORMAT(bb.order_date, "%Y-%m-%d") < DATE_FORMAT(#{form.endDate}, "%Y-%m-%d")
) t
AND t.regDentistId in
#{registeredDentistId}
and concat(IFNULL(t.`name`,''),IFNULL(t.pinyinName,''),IFNULL(t.mobile,'')) like concat(concat('%',#{form.combination}),'%')

SELECT bor.orderDate, bor.billId, bor.orderNum, bor.billNum, bor.patientId, bor.patientName, bor.mobile, bor.gender, bor.regDentistId, bor.regDentistName, IFNULL(bor.orderAmount,0) orderAmount, IFNULL(bor.privilegeAmount,0) privilegeAmount, IFNULL(bor.actualAmount,0) actualAmount, IFNULL(bor.receivedAmount,0) receivedAmount, bor.chargeStatus, bor.billerId, bor.biller FROM ( SELECT bb.org_id as orgId, DATE_FORMAT( bb.order_date, '%Y-%m-%d' ) AS orderDate, bb.bill_id AS billId, bb.order_num AS orderNum, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, bp.mobile AS mobile, bp.gender AS gender, btp.registered_dentist_id AS regDentistId, btp.employee_name AS regDentistName, bb.order_amount AS orderAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, IF( bb.bill_num IS NULL OR bb.bill_num='', 0, 1 ) AS chargeStatus, bb.biller_id AS billerId, be.employee_name AS biller FROM base_bill bb LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id, be.employee_name FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) btp ON bb.treatment_id = btp.treatment_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN base_employee be ON bb.biller_id = be.user_id ) bor
and bor.orgId = #{query.orgId}
and bor.orderNum like concat('%', #{query.orderNum} ,'%')
and bor.billNum like concat('%', #{query.billNum} ,'%')
and concat(IFNULL(bor.patientName, ''), IFNULL(bor.pinyinName, ''), IFNULL(bor.mobile, '')) like concat('%', #{query.keyWord}, '%')
and bor.orderDate >= #{query.orderStartDate}
and bor.orderDate <= #{query.orderEndDate}
and bor.regDentistId in
#{item}
ORDER BY bor.billId DESC

SELECT billId, orgId, DATE_FORMAT(orderDate, '%Y-%m-%d') orderDate, DATE_FORMAT(billDate, '%Y-%m-%d') billDate, billNum, patientId, patientName, mobile, regDentistId, regDentistName, IFNULL(totalOriginalAmount,0) totalOriginalAmount, IFNULL(totalActualAmount,0) totalActualAmount, IFNULL(billReceivableAmount,0) billReceivableAmount FROM ( SELECT bb.bill_id AS billId, bb.org_id as orgId, bb.bill_date AS billDate, bb.order_date AS orderDate, bb.bill_num AS billNum, bb.patient_id AS patientId, btp.`name` AS patientName, btp.pinyin_name as pinyinName, btp.mobile AS mobile, btp.registered_dentist_id AS regDentistId, btp.employee_name AS regDentistName, bb.order_amount AS totalOriginalAmount, bb.actual_amount AS totalActualAmount, bb.debt_amount AS billReceivableAmount FROM base_bill bb LEFT JOIN ( SELECT btp.treatment_id as treatment_id, any_value(btp.patient_id) as patient_id, any_value(bp.`name`) as name, any_value(bp.mobile) as mobile, any_value(bp.gender) as gender, any_value(bp.pinyin_name) as pinyin_name, any_value(btp.registered_dentist_id) as registered_dentist_id, any_value(be.employee_name) as employee_name FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treatment_id IS NOT NULL GROUP BY btp.treatment_id ) btp ON bb.treatment_id = btp.treatment_id ) brr
brr.billReceivableAmount>0
and brr.orgId = #{query.orgId}
AND date_format(brr.billDate, '%Y-%m-%d') = #{query.billDate}
AND date_format(brr.orderDate, '%Y-%m-%d') = #{query.orderDate}
and concat(IFNULL(brr.patientName, ''), IFNULL(brr.pinyinName, ''), IFNULL(brr.mobile, '')) like concat('%', #{query.keyword}, '%')
and brr.regDentistId in
#{item}
order by brr.billReceivableAmount desc

SELECT IFNULL(SUM( bb.totalOriginalAmount ), 0 ) AS totalOriginalAmount, IFNULL(SUM( bb.totalActualReceiveAmount ), 0) AS totalActualReceiveAmount, IFNULL(SUM( bb.totalDiscountAmount ), 0 ) AS totalDiscountAmount, IFNULL(SUM( bb.totalDebtAmount ), 0 ) AS totalDebtAmount, IFNULL(SUM(bb.totalFreePaymentAmount), 0) AS totalFreePaymentAmount FROM ( SELECT any_value(bb.org_id) as org_id, SUM( any_value(bb.order_amount) ) AS totalOriginalAmount, SUM( any_value(bb.privilege_amount) ) AS totalDiscountAmount, SUM( any_value(bb.actual_amount) ) AS totalActualReceiveAmount, SUM( any_value(bb.debt_amount) ) AS totalDebtAmount, SUM( any_value(bbpd.amount) ) AS totalFreePaymentAmount FROM base_bill bb INNER JOIN ( SELECT bill_id, IFNULL(SUM(principal_amount), 0) amount FROM base_bill_pay_detail
type = 2
AND account_item_id IN
#{id}
GROUP BY bill_id ) bbpd ON bbpd.bill_id=bb.bill_id
AND bb.bill_num IS NOT NULL
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m-%d') <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y-%m') <= #{query.endDate}
and DATE_FORMAT( bb.bill_date, '%Y') >= #{query.startDate}
and DATE_FORMAT( bb.bill_date, '%Y') <= #{query.endDate}
GROUP BY bb.org_id ) bb
and bb.org_id in
#{item}

SELECT bbd.orgId, bbd.orgName, bbd.billId, bbd.billDate, bbd.billNum, bbd.patientId, bbd.patientName, bbd.mobile, bbd.originalAmount, bbd.privilegeAmount, bbd.actualAmount, bbd.receivedAmount, bbd.remainingArrears FROM ( SELECT bbd.orgId, bbd.orgName, bbd.billId, bbd.billDate, bbd.billNum, bbd.patientId, bbd.patientName, bbd.pinyinName, bbd.mobile, bbd.originalAmount, bbd.privilegeAmount, bbd.actualAmount, bbd.receivedAmount, bbd.remainingArrears FROM ( SELECT any_value(bb.org_id) AS orgId, any_value(btp.registered_dentist_id) as registered_dentist_id, any_value(bo.abbreviation) AS orgName, any_value(bb.bill_id) AS billId, DATE_FORMAT(any_value(bb.bill_date), '%Y-%m-%d' ) AS billDate, any_value(bb.bill_num) AS billNum, any_value(bb.patient_id) AS patientId, any_value(bp.`name`) AS patientName, any_value(bp.pinyin_name) AS pinyinName, any_value(bp.mobile) as mobile, any_value(bb.originalAmount) as originalAmount, any_value(bb.privilegeAmount) as privilegeAmount, any_value(bb.actualAmount) as actualAmount, any_value(bb.receivedAmount) as receivedAmount, any_value(bb.remainingArrears) as remainingArrears FROM ( SELECT bb.org_id, bb.patient_id, bb.treatment_id, bb.bill_id, bb.bill_num, bb.bill_date, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS receivedAmount, bb.debt_amount AS remainingArrears FROM base_bill bb WHERE bb.debt_amount > 0 ) bb LEFT JOIN base_organization bo ON bb.org_id = bo.org_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN base_treatment_process btp ON bb.treatment_id = btp.treatment_id ) bbd
and bbd.registered_dentist_id = #{query.dentistId}
GROUP BY bbd.billId ) bbd
and bbd.billDate >= #{query.billStartDate}
and bbd.billDate <= #{query.billEndDate}
and concat(IFNULL(bbd.patientName, ''), IFNULL(bbd.pinyinName, ''), IFNULL(bbd.mobile, '')) like concat('%', #{query.keyword}, '%')

SELECT IFNULL(SUM( bb.actual_amount ), 0) AS totalActualAmountThisMonth, IFNULL(SUM( bb.privilege_amount ), 0) AS totalPrivilegeAmountThisMonth FROM base_bill bb
AND bb.bill_num IS NOT NULL AND bb.bill_date IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.order_date, '%Y-%m' ) = #{query.queryDate}

select #{query.queryDate} as currentMonth, #{query.orgId} as orgId, IFNULL(SUM( bb.actual_amount ), 0) as currentMonthTotalActualAmount, IFNULL(SUM( bb.privilege_amount ), 0) as currentMonthTotalDiscountAmount, IFNULL(SUM( bb.debt_amount ), 0) as currentMonthTotalDebtAmount from base_bill bb
AND bb.bill_date IS NOT NULL AND bb.bill_num IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) = #{query.queryDate}

SELECT bb.bill_id AS billId, DATE_FORMAT( bb.privilege_date, '%Y-%m-%d' ) AS collectDebtDate, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, bb.bill_num AS billNum, bb.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, btp.regDentistId AS regDentistId, btp.regDentistName AS regDentistName, bbp.payeeId, bbp.payeeName FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id LEFT JOIN ( SELECT btp.treatment_id, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL ) btp ON bb.treatment_id = btp.treatment_id LEFT JOIN ( SELECT bbp.bill_id, bbp.payee_date, bbp.payee_user_id AS payeeId, be.employee_name AS payeeName FROM base_bill_pay bbp LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id ) bbp ON bb.bill_id = bbp.bill_id AND bb.privilege_date = bbp.payee_date
AND bb.bill_date != bb.privilege_date
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.privilege_date, '%Y-%m' ) = #{query.currentMonth}

SELECT bri.item_num AS itemNum, bri.item_name AS itemName, bri.category_name AS categoryName, bbf.benefitAmount, bbf.quantity, bc.coupon_name AS couponName, case when bc.coupon_type=0 then '代金券' when bc.coupon_type=1 then '折扣券' when bc.coupon_type=2 then '兑换券' when bc.coupon_type=3 then '套餐券' end AS couponType, bb.bill_num AS billNum, bb.bill_date AS billDate, bbf.quantity * bbd.price AS originPrice, bp. NAME AS patientName, bp.mobile AS patientMobile, bbd.price AS price, be.employee_name AS executor, bcd.card_number AS cardNumber, bcd.sale_channel_name AS saleChannelName FROM(SELECT bbf.org_id as orgId, bbf.coupon_id AS couponId, bbf.order_id AS orderId, bbf.card_id AS cardId, bbf.item_id AS itemId, bbf.item_type AS itemType, sum(ifnull(bbf.benefit_amount,0)) benefitAmount, count(1) AS quantity, bbf.order_detail_id AS orderDetailId FROM base_benefit bbf WHERE bbf.choice_benefit_type = 0 and bbf.coupon_type in (0,1,2,3) GROUP BY bbf.org_id,bbf.order_id,bbf.coupon_id,bbf.order_detail_id,bbf.card_id,bbf.item_id,bbf.item_type ) bbf LEFT JOIN base_bill bb ON bb.bill_id = bbf.orderId LEFT JOIN base_bill_detail bbd ON bbd.bill_detail_id = bbf.orderDetailId LEFT JOIN base_coupon bc ON bc.coupon_id = bbf.couponId LEFT JOIN base_patient bp ON bp.patient_id = bb.patient_id LEFT JOIN base_employee be ON bbd.executor_id = be.user_id LEFT JOIN base_card bcd ON bbf.cardId = bcd.card_id LEFT JOIN base_tariff_info bri ON (bri.item_id = bbf.itemId AND bri.item_type = bbf.itemType)
bb.bill_num is not null
and bbf.orgId = #{query.orgId}
and concat(IFNULL(bp.name, ''), IFNULL(bp.pinyin_name, ''), IFNULL(bp.mobile, '')) like concat('%', #{query.keyWord}, '%')
and bri.category_id in
#{item}
and bc.coupon_name = #{query.couponName}
and bcd.card_number = #{query.cardNumber}
and DATE_FORMAT(bb.bill_date,'%Y-%m-%d') between DATE_FORMAT(#{query.orderStartDate},'%Y-%m-%d') and DATE_FORMAT(#{query.orderEndDate},'%Y-%m-%d')
order by bb.bill_id desc

select
distinct bb.bill_id as billId
from base_bill bb



            and DATE_FORMAT( bb.order_date, '%Y-%m' ) = #{query.queryDate}




            and DATE_FORMAT( bb.order_date, '%Y' ) = #{query.queryDate}

SELECT IFNULL(SUM(bb.actual_amount) ,0) AS totalActualReceivableAmount FROM base_bill bb
AND bb.bill_id IN
#{item}

select distinct bbp.bill_id from base_patient_origin_log log join base_bill bb on log.patient_id = bb.patient_id join base_bill_pay bbp on bbp.bill_id = bb.bill_id join (SELECT log.origin_id FROM base_patient_origin_log log JOIN base_employee ee ON log.origin_id = ee.user_id
log.origin_type = 1 and log.inservice = 1
and ee.user_id = #{query.employeeId}
and concat( IFNULL( ee.`employee_name`, '' )) LIKE concat( concat( '%', #{query.referrerName} ), '%' )
and ee.work_status = #{query.workStatus}
GROUP BY log.origin_id) t on t.origin_id = log.origin_id

select DISTINCT t.* from ( select bbd.bill_detail_id, bb.bill_id billId, bb.patient_id patientId, DATE_FORMAT( log.crt_time, '%Y-%m-%d %H:%i') relatedTime, bp.`name`, bp.mobile, DATE_FORMAT( bp.first_visit_date, '%Y-%m-%d %H:%i') firstVisitDate, DATE_FORMAT( bp.last_visit_date, '%Y-%m-%d %H:%i') lastVisitDate, DATE_FORMAT( bb.order_date, '%Y-%m-%d %H:%i') orderDate, bo.abbreviation abbreviation, be.employee_name employeeName, bti.item_name itemName, bbd.coupon_workload workload from base_bill_detail bbd join base_bill bb on bb.bill_id = bbd.bill_id join base_patient bp on bp.patient_id = bb.patient_id join base_patient_origin_log log on log.patient_id = bp.patient_id join base_organization bo on bo.org_id = bb.org_id join base_treatment_process btp on btp.treatment_id = bb.treatment_id join base_employee be on be.user_id = btp.registered_dentist_id join base_tariff_info bti ON bti.item_id = bbd.item_id where bb.privilege_date is not null and bbd.coupon_workload > 0 and log.origin_id = #{query.originId}
and DATE_FORMAT( bb.privilege_date, '%Y-%m-%d' ) >= DATE_FORMAT( #{query.startDate}, '%Y-%m-%d' )
and DATE_FORMAT( bb.privilege_date, '%Y-%m-%d' ) <= DATE_FORMAT( #{query.endDate}, '%Y-%m-%d' )
) t
